export const videoArchive: CanonicalVideoEntity[] = CANONICAL_VIDEO_ARCHIVE;

// Publicly visible videos (excludes broken/empty items like canonical-000786)
export const publicVideoArchive: CanonicalVideoEntity[] = CANONICAL_VIDEO_ARCHIVE.filter(
  (v) => !v.isExcluded && v.visibility === 'PUBLIC'
);

export function getVideoByCanonicalId(id: string): CanonicalVideoEntity | undefined {
  return CANONICAL_VIDEO_ARCHIVE.find((v) => v.canonicalId === id);
}

export function getVideoByCategory(category: CanonicalCategorySlug): CanonicalVideoEntity[] {
  return publicVideoArchive.filter((v) => v.category === category);
}

export function getVideoPlaylists(): CanonicalVideoEntity[] {
  return publicVideoArchive.filter((v) => v.isContainer);
}

export function getVideoLectures(): CanonicalVideoEntity[] {
  return publicVideoArchive.filter((v) => !v.isContainer);
}
